            As a genius expert, your task is to understand the content and provide
            the parsed objects in json that match the following json_schema:


            {
  "$defs": {
    "ContextRecallClassification": {
      "description": "Classification of a single statement.",
      "properties": {
        "statement": {
          "description": "Individual statement extracted from the answer",
          "title": "Statement",
          "type": "string"
        },
        "reason": {
          "description": "Reasoning for why the statement is or isn't attributable to context",
          "title": "Reason",
          "type": "string"
        },
        "attributed": {
          "description": "Binary classification: 1 if the statement can be attributed to context, 0 otherwise",
          "title": "Attributed",
          "type": "integer"
        }
      },
      "required": [
        "statement",
        "reason",
        "attributed"
      ],
      "title": "ContextRecallClassification",
      "type": "object"
    }
  },
  "description": "Structured output for context recall classifications.",
  "properties": {
    "classifications": {
      "description": "List of statement classifications",
      "items": {
        "$ref": "#/$defs/ContextRecallClassification"
      },
      "title": "Classifications",
      "type": "array"
    }
  },
  "required": [
    "classifications"
  ],
  "title": "ContextRecallOutput",
  "type": "object"
}

            Make sure to return an instance of the JSON, not the schema itself

